// HasResults applies the HasEdge predicate on the "results" edge.
func HasResults() predicate.IntelCheckTarget {
	return predicate.IntelCheckTarget(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ResultsTable, ResultsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasResultsWith applies the HasEdge predicate on the "results" edge with a given conditions (other predicates).
func HasResultsWith(preds ...predicate.IntelCheckResult) predicate.IntelCheckTarget {
	return predicate.IntelCheckTarget(func(s *sql.Selector) {
		step := newResultsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.IntelCheckTarget) predicate.IntelCheckTarget {
	return predicate.IntelCheckTarget(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IntelCheckTarget) predicate.IntelCheckTarget {
	return predicate.IntelCheckTarget(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IntelCheckTarget) predicate.IntelCheckTarget {
	return predicate.IntelCheckTarget(sql.NotPredicates(p))
}
